Lemma win_slice : forall m it0 bs a k, bytes_at usegs m it0 bs -> it0 <= a -> 0 <= k -> a + k <= it0 + Z.of_nat (length bs) ->
  bytes_at usegs m a (firstn (Z.to_nat k) (skipn (Z.to_nat (a - it0)) bs))
  /\ length (firstn (Z.to_nat k) (skipn (Z.to_nat (a - it0)) bs)) = Z.to_nat k.
Proof.
  intros m it0 bs a k WIN H1 H2 H3.
  destruct (win_suffix _ _ _ a WIN ltac:(lia)) as [WS LS].
  rewrite <- (firstn_skipn (Z.to_nat k) (skipn (Z.to_nat (a - it0)) bs)) in WS. apply bytes_at_app in WS. destruct WS as [W1 _].
  split; [exact W1|]. rewrite firstn_length_le; [reflexivity|]. rewrite length_skipn. lia.
Qed.

(* [comment removed for export] *)
Lemma tte_ok_facts : forall bs i, tte_class bs = TTE_ok i ->
  (i + 2 <= length bs)%nat /\ (exists c d, nth_error bs i = Some c /\ zb c = 13 /\ nth_error bs (S i) = Some d /\ zb d = 10).
Proof.
  intros bs i H. unfold tte_class in H.
  destruct (find_ix is_ctl bs) as [j|] eqn:F; [|discriminate].
  destruct (nth_error bs j) as [c|] eqn:N; [|discriminate].
  destruct (zb c =? 13) eqn:C; [|discriminate].
  destruct (nth_error bs (S j)) as [d|] eqn:N2; [|discriminate].
  destruct (zb d =? 10) eqn:D; [|discriminate]. injection H as <-.
  pose proof (nth_error_lt _ _ _ N2). split; [lia|]. exists c, d. repeat split; try fast_assumption; apply Z.eqb_eq; fast_assumption.
Qed.

