Definition pf_fctx (m m1 : mem) (sp : word) (sv : list word) (E L lo : Z) (p0 : Z) (bs : list byte)
    (tl : list byte) (tmp : list cell) (pv nlen : Z) (v1 v2 : word) (bsz : Z) (bb : list byte) (e1 e2 e3 : word) (g : bool) : Prop :=
  rw_cells usegs m1 (bv_unsigned sp + -160) [C8 (wz SLOT_A); C8 (wz (slotB sp)); C8 (wz (slotC sp))]
  /\ rw_cells usegs m1 (bv_unsigned sp + -136) [CB 8 tl]
  /\ rw_cells usegs m1 (bv_unsigned sp + -128) tmp
  /\ rw_cells usegs m1 (bv_unsigned sp + -104) (map C8 sv)
  /\ rw_cells usegs m1 (bv_unsigned sp + 40) [C8 (wz pv)]
  /\ rw_cells usegs m1 (bv_unsigned sp + 4168) [C8 (wz p0); C8 (wz nlen)]
  /\ rw_cells usegs m1 (bv_unsigned sp + 4152) [C8 v1; C8 v2]
  /\ rw_cells usegs m1 (bv_unsigned sp + 48) [C8 (wz bsz)]
  /\ u8arr usegs m1 (bv_unsigned sp + 56) bb /\ length bb = 4096%nat
  /\ rw_cells usegs m1 E [C8 e1; C8 e2; C8 e3]
  /\ bytes_at usegs m1 p0 bs /\ L = p0 + Z.of_nat (length bs) /\ rw_cells usegs m1 543976 [C8 (wz 89246)]
  /\ HttpCat m1 g /\ XStatics m1
  /\ stk usegs m1 lo (bv_unsigned sp + -160)
  /\ munch (pf_W lo sp E) m m1 /\ wmono usegs m m1 /\ mem_inv usegs m1.
