(* [comment removed for export] *)
Lemma pf_trim7 : forall (k : nat) (t : Z)
    rax spx gp tp t0 t1 t2 s0 s1 a0 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s7 s10 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (p0 p : Z) (bs : list byte),
  bytes_at usegs m1 p0 bs -> 0 < p0 -> p0 + Z.of_nat (length bs) < 2^64 ->
  p0 <= p -> p < t -> t <= p0 + Z.of_nat (length bs) -> (Z.to_nat (t - p) <= k)%nat ->
  evt usegs (fun ms' => exists t' a2' a3',
      ms' = MS (mkR rax spx gp tp t0 t1 t2 s0 s1 a0 (wz t') a2' a3' a4 a5 a6 a7 s2 s3 s4 s5 (wz p) s7 (wz 9) (wz 1) s10 (wz 32) t3 t4 t5 t6)
               F (Z_to_bv 64 0x3f0e0) fc None m1 (seg_rom usegs)
      /\ p <= t' <= t)
    (MS (mkR rax spx gp tp t0 t1 t2 s0 s1 a0 (wz t) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 (wz p) s7 (wz 9) (wz 1) s10 (wz 32) t3 t4 t5 t6)
