Definition PF_L6_AT (B : Z) : Prop :=
  forall (p : Z) rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7
         s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (E L lo : Z) (p0 : Z) (bs : list byte) (E0 : ecv)
    (tl : list byte) (tmp : list cell) (nlen : Z) (v1 v2 : word) (bsz : Z) (bb : list byte) (g : bool),
  pf_fctx m m1 sp (pf_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) E L lo p0 bs
          tl tmp p nlen v1 v2 bsz bb (wz (ec_val E0)) (wz (ec_cat E0)) (wz (ec_flags E0)) g ->
