(* [comment removed for export] *)
Definition pf_aftl_stmt (B : Z) : Prop :=
  forall (p q t' : Z) rax ra sp gp tp t0 t1 t2 a2 a3 a4 a5 a6 a7
         s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (E L lo : Z) (p0 : Z) (bs : list byte) (E0 : ecv)
    (tl : list byte) (tmp : list cell) (nlen : Z) (v1 v2 : word) (bsz : Z) (bb : list byte) (g : bool),
  PF_L6_AT B ->
  pf_fctx m m1 sp (pf_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) E L lo p0 bs
          tl tmp q nlen v1 v2 bsz bb (wz (ec_val E0)) (wz (ec_cat E0)) (wz (ec_flags E0)) g ->
  pf_purei sp E lo p0 bs E0 -> 0 <= bsz <= 4096 -> cells_size tmp = 24%nat ->
  p0 + 2 <= p -> 1 <= nlen -> p0 + nlen < p -> p <= t' -> t' + 2 <= q -> q + 1 <= L -> bsz + nlen + 3 <= p - p0 -> L - (q + 1) < B ->
  evt usegs (pf_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc E lo p0 bs E0 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -160)) gp tp t0 t1 t2 (wz E) (Z_to_bv 64 (bv_unsigned sp + 4152)) (wz q) (wz t') a2 a3 a4 a5 a6 a7
              (Z_to_bv 64 (bv_unsigned sp + 48)) (Z_to_bv 64 (bv_unsigned sp + 40)) (wz L) (wz 4096) (wz p) (Z_to_bv 64 (-1))
              (wz 9) (wz 1) (wz 2) (wz 32) t3 t4 t5 t6)
        F (Z_to_bv 64 0x3f0e0) fc None m1 (seg_rom usegs)).

